    <style>
        :root {
            bgcolor: 000000;
            headerfooterbg: rgba(10, 10, 10, 0.6);
            aibubblebg: rgba(0, 30, 60, 0.4);
            userbubblebg: lineargradient(135deg, rgba(0, 122, 255, 0.8), rgba(0, 86, 179, 0.8));
            widgetbg: rgba(28, 28, 30, 0.4);
            widgetborder: rgba(255, 255, 255, 0.06);
            textprimary: FFFFFF;
            textsecondary: A1A1AA;
            inputbg: rgba(28, 28, 30, 0.6);
            accentblue: 2997FF;
            accentresearchgradient: var(userbubblebg);
            safetop: env(safeareainsettop);
            safebottom: env(safeareainsetbottom);
            sidebarwidth: 280px;
        }

        sidebar {
            position: fixed;
            top: 0;
            left: 0;
            width: var(sidebarwidth);
            height: 100vh;
            background: rgba(0, 0, 0, 0.75);
            backdropfilter: blur(60px) saturate(220%);
            webkitbackdropfilter: blur(60px) saturate(220%);
            borderright: 1px solid var(widgetborder);
            zindex: 1000;
            transform: translateX(100%);
            transition: transform 0.4s cubicbezier(0.25, 1, 0.5, 1);
            display: flex;
            flexdirection: column;
            paddingtop: var(safetop);
            paddingbottom: var(safebottom);
        }

        sidebar.open {
            transform: translateX(0);
        }

        sidebaroverlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            background: rgba(0, 0, 0, 0.5);
            backdropfilter: blur(8px);
            webkitbackdropfilter: blur(8px);
            zindex: 999;
            opacity: 0;
            pointerevents: none;
            transition: opacity 0.4s cubicbezier(0.25, 1, 0.5, 1);
        }

        sidebaroverlay.visible {
            opacity: 1;
            pointerevents: auto;
        }

        sidebarheader {
            padding: 24px 20px 0;
            borderbottom: none;
            display: flex;
            alignitems: center;
            justifycontent: spacebetween;
            marginbottom: 20px;
        }

        sidebarheader h2 {
            fontsize: 1.1rem;
            fontweight: 500;
            color: var(textprimary);
            letterspacing: 0.02em;
        }

        sidebarclose {
            background: transparent;
            border: none;
            color: var(textsecondary);
            fontsize: 1.5rem;
            cursor: pointer;
            padding: 4px;
            width: 28px;
            height: 28px;
            display: flex;
            alignitems: center;
            justifycontent: center;
            transition: color 0.2s ease;
        }

        sidebarclose:hover {
            color: var(textprimary);
        }

        newchatbutton {
            margin: 0 20px 20px;
            padding: 10px 16px;
            background: rgba(41, 151, 255, 0.1);
            backdropfilter: blur(20px) saturate(200%);
            webkitbackdropfilter: blur(20px) saturate(200%);
            color: var(accentblue);
            border: 1px solid rgba(41, 151, 255, 0.2);
            borderradius: 10px;
            fontsize: 0.9rem;
            fontweight: 500;
            cursor: pointer;
            display: flex;
            alignitems: center;
            justifycontent: center;
            gap: 8px;
            transition: all 0.2s ease;
        }

        newchatbutton:hover {
            background: rgba(41, 151, 255, 0.2);
            bordercolor: rgba(41, 151, 255, 0.4);
            transform: translateY(1px);
        }

        newchatbutton svg {
            width: 16px;
            height: 16px;
        }

        pastchatscontainer {
            flex: 1;
            overflowy: auto;
            padding: 0 20px;
            webkitoverflowscrolling: touch;
            scrollbarwidth: thin;
            scrollbarcolor: rgba(255, 255, 255, 0.15) transparent;
        }

        pastchatscontainer::webkitscrollbar {
            width: 4px;
        }

        pastchatscontainer::webkitscrollbartrack {
            background: transparent;
        }

        pastchatscontainer::webkitscrollbarthumb {
            background: rgba(255, 255, 255, 0.15);
            borderradius: 2px;
        }

        .pastchatitem {
            padding: 14px 16px;
            marginbottom: 4px;
            background: rgba(255, 255, 255, 0.02);
            border: 1px solid transparent;
            borderradius: 12px;
            cursor: pointer;
            transition: all 0.2s ease;
            position: relative;
        }

        .pastchatitem::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: transparent;
            borderradius: 12px;
            transition: background 0.2s ease;
        }

        .pastchatitem:hover::before {
            background: rgba(41, 151, 255, 0.1);
        }

        .pastchatitem.active::before {
            background: rgba(41, 151, 255, 0.2);
        }

        .pastchatitem:hover {
            bordercolor: rgba(41, 151, 255, 0.3);
        }

        .pastchatitem.active {
            bordercolor: var(accentblue);
        }

        .pastchattitle {
            fontsize: 0.95rem;
            fontweight: 500;
            color: var(textprimary);
            marginbottom: 2px;
            whitespace: nowrap;
            overflow: hidden;
            textoverflow: ellipsis;
        }

        .pastchatitem.active .pastchattitle {
            color: var(textprimary);
        }

        .pastchatdate {
            fontsize: 0.75rem;
            color: var(textsecondary);
            letterspacing: 0.01em;
        }

        .pastchatitem.active .pastchatdate {
            color: rgba(255, 255, 255, 0.7);
        }

        menutoggle {
            background: transparent;
            border: none;
            color: var(textsecondary);
            padding: 6px;
            cursor: pointer;
            display: flex;
            alignitems: center;
            justifycontent: center;
            transition: color 0.2s ease;
        }

        menutoggle:hover {
            color: var(textprimary);
        }

        menutoggle svg {
            width: 20px;
            height: 20px;
        }

         {
            boxsizing: borderbox;
            margin: 0;
            padding: 0;
        }

        html {
            scrollbehavior: smooth;
        }

        body {
            fontfamily: applesystem, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sansserif;
            background: var(bgcolor);
            color: var(textprimary);
            height: 100dvh;
            width: 100vw;
            display: flex;
            flexdirection: column;
            overflow: hidden;
        }

        canvasbg {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            zindex: 1;
            opacity: 0.12;
        }

        chatview {
            display: flex;
            flexdirection: column;
            width: 100%;
            height: 100%;
            background: transparent;
            transition: transform 0.5s cubicbezier(0.25, 1, 0.5, 1), filter 0.5s cubicbezier(0.25, 1, 0.5, 1), borderradius 0.5s cubicbezier(0.25, 1, 0.5, 1);
        }

        chatview.researchactive {
            transform: scale(0.98);
            filter: brightness(0.85);
            borderradius: 24px;
            overflow: hidden;
            pointerevents: none;
        }

        .frostedheader {
            position: sticky;
            top: 0;
            width: 100%;
            background: var(headerfooterbg);
            backdropfilter: blur(30px) saturate(200%);
            webkitbackdropfilter: blur(30px) saturate(200%);
            zindex: 10;
            padding: 16px 20px;
            paddingtop: calc(16px + var(safetop));
            borderbottom: 1px solid var(widgetborder);
            display: flex;
            alignitems: center;
            justifycontent: spacebetween;
        }

        .frostedheader h1 {
            fontsize: 1.05rem;
            fontweight: 500;
            opacity: 0.95;
            flex: 1;
            textalign: center;
            letterspacing: 0.02em;
        }

        chathistory {
            flexgrow: 1;
            overflowy: auto;
            webkitoverflowscrolling: touch;
            padding: 1.75rem 1.25rem;
            display: flex;
            flexdirection: column;
            gap: 1.5rem;
            scrollbehavior: smooth;
        }

        @keyframes messagepopin {
            from {
                opacity: 0;
                transform: translateY(8px) scale(0.98);
            }
            to {
                opacity: 1;
                transform: translateY(0) scale(1.0);
            }
        }

        .message {
            maxwidth: 85%;
            padding: 14px 20px;
            borderradius: 22px;
