            padding: 14px 20px;
            alignself: flexstart;
            border: 1px solid rgba(255, 255, 255, 0.06);
        }

        .messagewrapper {
            display: flex;
            flexdirection: column;
            gap: 8px;
            maxwidth: 85%;
            width: auto;
        }

