            top: 0;
            left: 0;
            zindex: 100;
            background: 000000;
            backdropfilter: none;
            webkitbackdropfilter: none;
            boxshadow: none;
            border: none;
            transform: translateX(100%);
            transition: transform 0.5s cubicbezier(0.25, 1, 0.5, 1);
            overflow: hidden;
        }

        researchview.visible {
            transform: translateX(0);
        }

        researchheader {
            padding: 16px 20px;
            paddingtop: calc(16px + var(safetop));
            paddingleft: 12px;
            justifycontent: spacebetween;
            flexshrink: 0;
            borderbottom: 1px solid var(widgetborder);
        }

        researchbackbutton {
            background: transparent;
            border: none;
            color: var(accentblue);
            fontsize: 0.95rem;
            fontweight: 500;
            cursor: pointer;
            display: flex;
            alignitems: center;
            gap: 4px;
            padding: 6px 10px;
            transition: color 0.2s ease;
            borderradius: 8px;
        }

        researchbackbutton:hover {
            color: var(textprimary);
            background: rgba(41, 151, 255, 0.1);
        }

        researchbackbutton svg {
            width: 20px;
            height: 20px;
        }

        researchtitle {
            fontsize: 1.05rem;
            fontweight: 500;
            whitespace: nowrap;
            overflow: hidden;
            textoverflow: ellipsis;
            maxwidth: 60%;
            letterspacing: 0.02em;
        }

        researchcontent {
            flex: 1;
            overflowy: auto;
            overflowx: hidden;
            padding: 1.75rem 1.25rem;
            paddingbottom: calc(1.75rem + var(safebottom));
            display: flex;
            flexdirection: column;
            gap: 28px;
            webkitoverflowscrolling: touch;
            scrollbarwidth: thin;
            scrollbarcolor: rgba(255, 255, 255, 0.15) transparent;
        }

        researchcontent::webkitscrollbar {
            width: 4px;
        }

        researchcontent::webkitscrollbartrack {
            background: transparent;
        }

        researchcontent::webkitscrollbarthumb {
            background: rgba(255, 255, 255, 0.15);
            borderradius: 2px;
        }

        .researchsectiontitle {
