            alignitems: center;
            gap: 20px;
            backdropfilter: blur(20px);
            webkitbackdropfilter: blur(20px);
            overflow: hidden;
        }

        .agentprogressdonut {
            flexshrink: 0;
        }

        .agentprogressdonut .donutfg {
            transition: strokedashoffset 0.5s easeout;
        }

        .agentprogressdonut .donuttext {
            fontsize: 11px;
            fontweight: 600;
            fill: var(textprimary);
        }

        .agentcardinfo {
            minwidth: 0;
        }

        .agentcardinfo .agentcardtitle {
            fontsize: 0.95rem;
            fontweight: 500;
