            whitespace: prewrap;
            overflowwrap: breakword;
        }

        .similarlinkitem, .websetitem {
            display: flex;
            alignitems: center;
            gap: 16px;
            padding: 16px;
            background: rgba(28, 28, 30, 0.4);
            border: 1px solid rgba(255, 255, 255, 0.06);
            borderradius: 14px;
            backdropfilter: blur(15px);
            webkitbackdropfilter: blur(15px);
            overflow: hidden;
        }

        .iconplaceholder {
            width: 40px;
            height: 40px;
            flexshrink: 0;
            background: rgba(44, 44, 46, 0.6);
            borderradius: 10px;
            display: flex;
            alignitems: center;
            justifycontent: center;
        }

        .iconplaceholder svg {
            width: 20px;
            height: 20px;
            color: var(textsecondary);
        }

        .itemtext {
