            alignitems: center;
            justifycontent: center;
            width: 100%;
            padding: 8px;
            borderradius: 8px;
            transition: background 0.2s ease;
        }

        toggleadvancedoptions:hover {
            background: rgba(41, 151, 255, 0.1);
        }

        advancedoptionscontainer {
            bordertop: 1px solid var(widgetborder);
            paddingtop: 24px;
            marginbottom: 24px;
            display: none;
        }

